function n(r){return typeof r=="string"&&(r=Number(r)),String(r/100)}function e(r){const t=String(r).trim(),[i,c=""]=t.split(".");return parseInt(i,10)*100+parseInt((c+"00").slice(0,2),10)}function o(r){return{...r,price:n(r.price)}}function u(r){return r.map(t=>({...t,price:n(t.price)}))}function s(r){return{...r,price:e(r.price)}}function a(r){return r.map(t=>({...t,price:e(t.price)}))}export{u as a,s as b,a as d,o as n};
